// Pure vendor-snapshot comparison logic — no network, no DOM, no filesystem.
// Ports the same rules as src/vendor_change.py (the CLI this venture shipped
// with first) so the browser tool and the CLI agree on every verdict.
// Loadable as a plain <script> in the browser (defines globals, no bundler)
// and requireable under `node --test`.

const REQUIRED = ["url", "captured_at", "fetch_status", "text"];

/** Parses and validates one snapshot object. Throws a visitor-facing message. */
function parseSnapshot(text, label) {
  let value;
  try {
    value = JSON.parse(text);
  } catch {
    throw new Error(`The ${label} snapshot is not valid JSON.`);
  }
  if (value === null || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`The ${label} snapshot is not valid JSON.`);
  }
  for (const key of REQUIRED) {
    if (!(key in value)) {
      throw new Error(`The ${label} snapshot is missing "${key}". Snapshots need url, captured_at, fetch_status, and text.`);
    }
    if (typeof value[key] !== "string" || value[key].trim() === "") {
      throw new Error(`The ${label} snapshot's "${key}" must be a non-empty string.`);
    }
  }
  if (Number.isNaN(Date.parse(value.captured_at))) {
    throw new Error(`The ${label} snapshot's "captured_at" must be an ISO 8601 timestamp.`);
  }
  return value;
}

/** Compares two validated snapshots. Mirrors vendor_change.py's compare() exactly. */
function compare(before, after) {
  const beforeTime = Date.parse(before.captured_at);
  const afterTime = Date.parse(after.captured_at);
  const metadata = {
    url_before: before.url,
    url_after: after.url,
    captured_before: before.captured_at,
    captured_after: after.captured_at,
    fetch_status_before: before.fetch_status,
    fetch_status_after: after.fetch_status,
  };
  const changes = [];
  if (before.url !== after.url) {
    changes.push({ kind: "source_changed", before: before.url, after: after.url });
  }
  if (before.fetch_status !== "ok" || after.fetch_status !== "ok") {
    changes.push({ kind: "fetch_inconclusive", before: before.fetch_status, after: after.fetch_status });
  }
  if (before.text !== after.text) {
    changes.push({ kind: "content_changed", before_length: before.text.length, after_length: after.text.length });
  }
  if (afterTime < beforeTime) {
    changes.push({ kind: "capture_order_invalid" });
  }
  const inconclusive = changes.some((item) => item.kind === "fetch_inconclusive" || item.kind === "capture_order_invalid");
  const status = inconclusive ? "inconclusive" : changes.length ? "changed" : "unchanged";
  return {
    status,
    metadata,
    changes,
    review_required: changes.length > 0,
    evidence_boundary: "Reports observations; the customer decides contractual or security significance.",
  };
}

/** Builds a report directly from raw before/after snapshot text. */
function buildReport(beforeText, afterText) {
  const before = parseSnapshot(beforeText, "before");
  const after = parseSnapshot(afterText, "after");
  return compare(before, after);
}

function toMarkdown(report) {
  const lines = [
    "# Vendor snapshot review",
    "",
    `**Status:** \`${report.status}\``,
    "",
    `**Review required:** ${report.review_required ? "yes" : "no"}`,
    "",
    `- Before: \`${report.metadata.url_before}\` captured ${report.metadata.captured_before} (fetch: ${report.metadata.fetch_status_before})`,
    `- After: \`${report.metadata.url_after}\` captured ${report.metadata.captured_after} (fetch: ${report.metadata.fetch_status_after})`,
    "",
    "## Changes",
    "",
  ];
  if (report.changes.length === 0) {
    lines.push("- none observed");
  } else {
    for (const change of report.changes) lines.push(`- \`${change.kind}\``);
  }
  lines.push(
    "",
    `> ${report.evidence_boundary}`,
    "",
    "**No warranty.** This tool is provided free and as-is, without warranty of any kind, express or implied. It is not legal, security, or compliance advice, and it does not replace a qualified professional. **You are responsible for reviewing and verifying its output before relying on it**, and for meeting any obligation it helps you prepare for. To the maximum extent permitted by law, the authors accept no liability for any loss or damage arising from its use.",
  );
  return lines.join("\n") + "\n";
}

function toJson(report) {
  return JSON.stringify(report, null, 2) + "\n";
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { parseSnapshot, compare, buildReport, toMarkdown, toJson, REQUIRED };
}

style.css.text:
:root {
  color-scheme: light dark;
  --bg: #ffffff;
  --fg: #1a1a1a;
  --muted: #5f6368;
  --border: #e2e2e2;
  --accent: #2563eb;
  --good: #16a34a;
  --warn: #d97706;
  --card-bg: #f8f9fa;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, Menlo, monospace;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --fg: #f1f2f4;
    --muted: #9aa0a6;
    --border: #2c2f34;
    --card-bg: #1c1f24;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
  font-family: var(--font);
  line-height: 1.5;
}

.page {
  max-width: 760px;
  margin: 0 auto;
  padding: 2.5rem 1.25rem 4rem;
}

.hero {
  text-align: center;
  margin-bottom: 2rem;
}

.hero h1 {
  font-size: 2rem;
  margin: 0 0 0.5rem;
}

.tagline {
  color: var(--muted);
  font-size: 1.05rem;
  margin: 0 auto;
  max-width: 56ch;
}

.tagline code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.drop-zone {
  border: 2px dashed var(--border);
  border-radius: 12px;
  padding: 1.75rem 1.25rem;
  text-align: center;
  background: var(--card-bg);
}

.drop-zone p {
  margin: 0.4rem 0 0.9rem;
  color: var(--muted);
}

.snapshot-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  text-align: left;
}

@media (max-width: 560px) {
  .snapshot-grid {
    grid-template-columns: 1fr;
  }
}

.snapshot-col label {
  display: block;
  font-weight: 600;
  font-size: 0.85rem;
  margin-bottom: 0.3rem;
}

.snapshot-col textarea {
  width: 100%;
  font-family: var(--mono);
  font-size: 0.8rem;
  padding: 0.6rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  resize: vertical;
}

#compare-button {
  margin-top: 1rem;
  padding: 0.6rem 1.1rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  background: var(--accent);
  border: none;
  border-radius: 8px;
  cursor: pointer;
}

#compare-button:hover {
  filter: brightness(1.08);
}

.example-line {
  text-align: center;
  font-size: 0.95rem;
  opacity: 0.85;
  max-width: 50rem;
  margin: 0.9rem auto 0;
}

.link-button {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  color: inherit;
  text-decoration: underline;
  cursor: pointer;
}

.link-button:hover {
  filter: brightness(1.3);
}

.link-button:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.error {
  text-align: center;
  color: #dc2626;
  font-weight: 600;
}

.summary-card {
  display: flex;
  justify-content: center;
  gap: 2rem;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 1.25rem;
  margin: 1.5rem 0 1rem;
  background: var(--card-bg);
}

.summary-stat {
  text-align: center;
}

.summary-number {
  display: block;
  font-size: 1.6rem;
  font-weight: 800;
  text-transform: capitalize;
}

.summary-number.changed,
.summary-number.build-only { color: var(--warn); }
.summary-number.unchanged,
.summary-number.production { color: var(--good); }
.summary-number.inconclusive { color: #dc2626; }

.summary-label {
  font-size: 0.8rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.report-actions {
  display: flex;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}

.report-actions button {
  padding: 0.55rem 1rem;
  font-size: 0.9rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  cursor: pointer;
}

.report-actions button:hover {
  border-color: var(--accent);
}

.table-wrap {
  font-size: 0.9rem;
}

.change-list {
  padding-left: 1.25rem;
}

.change-list code {
  font-family: var(--mono);
  font-size: 0.85em;
}

.reason {
  color: var(--muted);
}

.disclaimer {
  margin-top: 3rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--border);
  font-size: 0.9rem;
  color: var(--muted);
}

.disclaimer h2 {
  font-size: 1rem;
  color: var(--fg);
}

.disclaimer code {
  font-family: var(--mono);
  font-size: 0.9em;
}

.footer {
  margin-top: 2rem;
  text-align: left;
  font-size: 0.85rem;
  color: var(--muted);
}

.footer p {
  margin: 0.75rem 0;
}

.privacy {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  margin: 0.75rem 0;
}

usage.js.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No snapshot text, no URLs, no file names — just
// an event name and a day, kept in this browser's own localStorage. Nothing
// is sent anywhere; there is no server for it to go to. Off-switchable, and
// honors Do Not Track / Global Privacy Control.

const STORAGE_KEY = "vendor-change-evidence:usage";
const OPT_OUT_KEY = "vendor-change-evidence:usage:off";

function hasStorage() {
  try { return typeof localStorage !== "undefined"; } catch { return false; }
}

function browserOptedOut() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

function isUsageEnabled() {
  if (!hasStorage() || browserOptedOut()) return false;
  try { return localStorage.getItem(OPT_OUT_KEY) !== "1"; } catch { return false; }
}

function setUsageEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch { /* usage must never affect the report */ }
}

function recordUsage(eventName) {
  if (!isUsageEnabled() || !eventName) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const events = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch { /* private browsing and full storage are expected */ }
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { isUsageEnabled, setUsageEnabled, recordUsage, STORAGE_KEY, OPT_OUT_KEY };
}
